class Solution {
    public int[][] matrixReshape(int[][] mat,int r,int c){
        int rows=mat.length,columns=mat[0].length;
        if(rows*columns!=r*c)return mat;
        int[][] result=new int[r][c];
        for(int index=0;index<rows*columns;index++)result[index/c][index%c]=mat[index/columns][index%columns];
        return result;
    }
}

code.kotlin:
class Solution {
    fun matrixReshape(mat:Array<IntArray>,r:Int,c:Int):Array<IntArray>{
        val rows=mat.size;
        val columns=mat[0].size;
        if(rows*columns!=r*c)return mat;
        val result=Array(r){
            IntArray(c)
        };
        for(index in 0 until rows*columns)result[index/c][index%c]=mat[index/columns][index%columns];
        return result
    }
}

